from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/vibe")
def read_vibe():
    return {"message": "vibe check passed"}

client = TestClient(app)

def test_vibe():
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}
    print("Test passed!")

if __name__ == "__main__":
    test_vibe()
